 "content": "from collections import Counter, deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    replacements = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if len(component) == 1:
                y, x = component[0]
                neighbors = [grid[ny][nx]
                             for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1))
                             if 0 <= (ny := y + dy) < h and 0 <= (nx := x + dx) < w]
                if neighbors:
                    counts = Counter(neighbors)
                    high = max(counts.values())
                    replacements.append((y, x, min(k for k, v in counts.items() if v == high)))
    for r, c, color in replacements:
        out[r][c] = color
    return out


